const body = $json.body || $json;
const invoice = body.invoice || {};
const items = Array.isArray(body.items) ? body.items : [];

const factoryId = String(body.factory_id || invoice.factory_id || 'factory');
const invoiceId = invoice.invoice_id || invoice.id || (Array.isArray(invoice.sale_ids) ? invoice.sale_ids[0] : undefined) || body.invoice_id || Date.now();
const invoiceDate = invoice.invoice_date || body.invoice_date || new Date().toISOString().slice(0, 10);
const customerName = invoice.customer_name || body.customer_name || '';
const customerPhone = invoice.customer_phone || body.customer_phone || '';
const paymentMethod = invoice.payment_method || body.payment_method || 'Cash';
const billTotal = Number(invoice.bill_total ?? body.bill_total ?? 0);
const amountPaid = Number(invoice.amount_paid ?? body.amount_paid ?? 0);
const customerTotalDue = Number(invoice.customer_total_due ?? body.customer_total_due ?? Math.max(billTotal - amountPaid, 0));
const pdfFilename = `invoice_${factoryId}_${invoiceId}.pdf`.replace(/[^a-zA-Z0-9_.-]/g, '_');

return [{
  json: {
    factory_id: factoryId,
    invoice_id: String(invoiceId),
    invoice_date: invoiceDate,
    customer_name: customerName,
    customer_phone: customerPhone,
    payment_method: paymentMethod,
    bill_total: billTotal,
    amount_paid: amountPaid,
    customer_total_due: customerTotalDue,
    items,
    pdf_filename: pdfFilename,
    pdf_path: `/files/invoices/${pdfFilename}`
  }
}];

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#039;');

const money = (value) => `Rs ${Number(value || 0).toFixed(2)}`;
const itemRows = ($json.items || []).map((item, index) => {
  const name = item.product_name || item.name || `${item.product_size_ml || ''}${item.product_size_ml ? ' ml' : ''} ${item.variety || ''}`.trim() || `Item ${index + 1}`;
  const packaging = item.packaging_size_name || item.packaging || item.unit || '';
  const quantity = item.quantity ?? item.boxes_sold ?? item.loose_packets_sold ?? 0;
  const rate = item.rate ?? item.rate_per_box ?? item.unit_price ?? 0;
  const total = item.line_total ?? item.total ?? (Number(quantity || 0) * Number(rate || 0));
  return `<tr>
    <td>${index + 1}</td>
    <td>${escapeHtml(name)}</td>
    <td>${escapeHtml(packaging)}</td>
    <td class="num">${escapeHtml(quantity)}</td>
    <td class="num">${money(rate)}</td>
    <td class="num">${money(total)}</td>
  </tr>`;
}).join('') || '<tr><td colspan="6" class="empty">No line items received</td></tr>';

const html = `<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Invoice ${escapeHtml($json.invoice_id)}</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; padding: 32px; color: #111827; font-family: Arial, Helvetica, sans-serif; font-size: 13px; }
    .header { display: flex; justify-content: space-between; gap: 24px; border-bottom: 2px solid #111827; padding-bottom: 18px; margin-bottom: 24px; }
    h1 { margin: 0 0 8px; font-size: 28px; letter-spacing: 0; }
    .muted { color: #4b5563; }
    .meta { text-align: right; line-height: 1.7; }
    .section { margin-top: 20px; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .box { border: 1px solid #d1d5db; padding: 14px; }
    .label { display: block; color: #4b5563; font-size: 11px; text-transform: uppercase; margin-bottom: 4px; }
    table { width: 100%; border-collapse: collapse; margin-top: 18px; }
    th { background: #f3f4f6; text-align: left; font-size: 12px; border: 1px solid #d1d5db; padding: 9px; }
    td { border: 1px solid #d1d5db; padding: 9px; vertical-align: top; }
    .num { text-align: right; white-space: nowrap; }
    .empty { text-align: center; color: #6b7280; }
    .summary { margin-top: 22px; margin-left: auto; width: 320px; border: 1px solid #d1d5db; }
    .summary-row { display: flex; justify-content: space-between; padding: 10px 14px; border-bottom: 1px solid #e5e7eb; }
    .summary-row:last-child { border-bottom: 0; }
    .total { font-weight: 700; font-size: 15px; background: #f9fafb; }
  </style>
</head>
<body>
  <div class="header">
    <div>
      <h1>Invoice</h1>
      <div class="muted">Generated by Munshi AI</div>
    </div>
    <div class="meta">
      <div><strong>Invoice No:</strong> ${escapeHtml($json.invoice_id)}</div>
      <div><strong>Date:</strong> ${escapeHtml($json.invoice_date)}</div>
      <div><strong>Factory ID:</strong> ${escapeHtml($json.factory_id)}</div>
    </div>
  </div>

  <div class="grid section">
    <div class="box">
      <span class="label">Customer</span>
      <strong>${escapeHtml($json.customer_name || '-')}</strong><br />
      <span class="muted">${escapeHtml($json.customer_phone || '-')}</span>
    </div>
    <div class="box">
      <span class="label">Payment Method</span>
      <strong>${escapeHtml($json.payment_method || '-')}</strong>
    </div>
  </div>

  <div class="section">
    <table>
      <thead>
        <tr><th>#</th><th>Item</th><th>Packaging</th><th class="num">Qty</th><th class="num">Rate</th><th class="num">Amount</th></tr>
      </thead>
      <tbody>${itemRows}</tbody>
    </table>
  </div>

  <div class="summary">
    <div class="summary-row"><span>Bill Total</span><strong>${money($json.bill_total)}</strong></div>
    <div class="summary-row"><span>Paid Amount</span><strong>${money($json.amount_paid)}</strong></div>
    <div class="summary-row total"><span>Total Due</span><span>${money($json.customer_total_due)}</span></div>
  </div>
</body>
</html>`;

return [{ json: { ...$json, invoice_html: html } }];

const html = $json.invoice_html || '<html><body>Missing invoice HTML</body></html>';
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: $json, binary: { data: binary } }];
